{"kode":"work_life_balance","label":"Work-Life Balance","nilai":70,"kategori":"Tinggi"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Karakter Lembaga paling kuat Anda rasakan (80), sedangkan Manajemen paling rendah (55) dengan harapan 80.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":80,"kategori":"Sangat Tinggi","harapan":70,"gap":-10},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":60,"kategori":"Tinggi","harapan":65,"gap":5},{"kode":"management","label":"Manajemen","nilai":55,"kategori":"Sedang","harapan":80,"gap":25},{"kode":"sinergi","label":"Sinergi Tim","nilai":65,"kategori":"Tinggi","harapan":65,"gap":0},{"kode":"fokus","label":"Fokus Strategis","nilai":65,"kategori":"Tinggi","harapan":60,"gap":-5},{"kode":"performance","label":"Kinerja/Performa","nilai":60,"kategori":"Tinggi","harapan":65,"gap":5}]},"bagian_cermin":"\"Rekan satu jenjang gampang diajak diskusi kalau ada murid yang butuh perhatian khusus.\" \"Jadwal kegiatan tambahan yang sering muncul mendadak.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Kekeluargaan jadi sisi budaya yang paling terasa di TK Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Satu hal apa yang ingin Anda tanyakan langsung ke pimpinan unit bulan ini, yang selama ini cuma Anda simpan sendiri?","jawaban_survey":{"betah":"Rekan satu jenjang gampang diajak diskusi kalau ada murid yang butuh perhatian khusus.","hal_menguras_energi":"Jadwal kegiatan tambahan yang sering muncul mendadak.","yang_ingin_disampaikan":"Semoga ide dari guru yang lebih muda juga diberi ruang untuk dicoba.","yang_ingin_diubah":"Evaluasi program dijalankan rutin, bukan cuma saat ada masalah.","gambaran_lembaga":"keluarga besar yang saling menutupi kekurangan"},"rencana_aksi":[{"id":"3cd0d2fb-ad7c-4296-a3ce-09410854f96d-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 20,6 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"3cd0d2fb-ad7c-4296-a3ce-09410854f96d-aksi-2","judul":"Bawa satu masalah nyata ke pimpinan unit.","alasan":"Kepuasan pada Kepemimpinan jadi sisi terendah Anda. Menyampaikan satu masalah konkret dengan usulan solusinya membuka percakapan yang selama ini tertunda. Angkanya sekarang 60 dari 100.","terkait":"Kepuasan pada Kepemimpinan","jangka":"Bulan ini","ikon":"🗣️"},{"id":"3cd0d2fb-ad7c-4296-a3ce-09410854f96d-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 90 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Kepuasan pada Kepemimpinan jadi sisi kesejahteraan terendah Anda (60 dari 100), sementara Kenyamanan Bekerja sudah kuat di 90. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Catat pola masalah sebelum menyampaikannya","instruksi":"Selama dua minggu, catat setiap kali:","contoh":["Keputusan yang tidak jelas dasarnya.","Informasi yang datang terlambat.","Dampaknya pada pekerjaan Anda hari itu."],"tujuan":"Supaya yang Anda sampaikan berupa pola, bukan kesan sesaat."},{"judul":"Siapkan satu usulan, bukan cuma keluhan","instruksi":"Untuk satu masalah yang paling sering muncul, tuliskan:","contoh":["Apa yang terjadi sekarang.","Apa yang Anda usulkan.","Apa yang Anda siap kerjakan sendiri."],"tujuan":"Percakapan dengan pimpinan berjalan lebih jauh kalau ada usulan konkret di dalamnya."},{"judul":"Pilih waktu bicara yang bukan saat genting","instruksi":"Cari satu momen tenang untuk bicara, misalnya:","contoh":["Setelah jam mengajar terakhir.","Di luar minggu ujian.","Bukan lewat pesan singkat."],"tujuan":"Isi pembicaraan lebih terdengar kalau waktunya tepat."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 20,6 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Manajemen jadi dimensi profil organisasi terendah menurut Anda (55 dari 100, harapan 80). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Usulkan penyederhanaan satu laporan","instruksi":"Pilih laporan yang paling memakan waktu, lalu:","contoh":["Tandai bagian yang datanya sudah ada di tempat lain.","Hitung waktu yang habis tiap bulan.","Sampaikan ke bagian yang memintanya."],"tujuan":"Waktu administrasi yang kembali langsung terasa di jam mengajar."},{"judul":"Bantu bakukan satu alur yang sering berubah","instruksi":"Bersama unit Anda, sepakati:","contoh":["Format yang dipakai seterusnya.","Tenggat yang realistis.","Siapa yang menjawab kalau ada pertanyaan."],"tujuan":"Format yang stabil menghilangkan pekerjaan ulang yang tidak perlu."},{"judul":"Ajukan kalender kegiatan satu semester","instruksi":"Usulkan ke pimpinan:","contoh":["Kegiatan tetap yang sudah pasti.","Batas waktu penambahan kegiatan baru.","Cara mengumumkan perubahan."],"tujuan":"Kepastian jadwal adalah keluhan yang paling sering muncul dan paling mudah diperbaiki."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
