life_balance","label":"Work-Life Balance","nilai":40,"kategori":"Rendah"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Fokus Strategis paling kuat Anda rasakan (75), sedangkan Kepemimpinan paling rendah (50) dengan harapan 60.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":70,"kategori":"Tinggi","harapan":60,"gap":-10},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":50,"kategori":"Sedang","harapan":60,"gap":10},{"kode":"management","label":"Manajemen","nilai":70,"kategori":"Tinggi","harapan":70,"gap":0},{"kode":"sinergi","label":"Sinergi Tim","nilai":50,"kategori":"Sedang","harapan":65,"gap":15},{"kode":"fokus","label":"Fokus Strategis","nilai":75,"kategori":"Sangat Tinggi","harapan":60,"gap":-15},{"kode":"performance","label":"Kinerja/Performa","nilai":65,"kategori":"Tinggi","harapan":70,"gap":5}]},"bagian_cermin":"\"Sekolah memberi kepercayaan untuk mengelola kelas dengan cara sendiri.\" \"Pekerjaan yang terbawa sampai rumah hampir setiap malam.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Kekeluargaan jadi sisi budaya yang paling terasa di TK Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Jam berapa Anda ingin benar-benar berhenti bekerja hari ini, dan apa yang perlu disiapkan supaya itu terjadi?","jawaban_survey":{"betah":"Sekolah memberi kepercayaan untuk mengelola kelas dengan cara sendiri.","hal_menguras_energi":"Pekerjaan yang terbawa sampai rumah hampir setiap malam.","yang_ingin_disampaikan":"Semoga jam pulang benar-benar dihormati.","yang_ingin_diubah":"Jalur menyampaikan ide dibuat jelas, tidak berhenti di tengah jalan.","gambaran_lembaga":"mesin yang jalan rapi tapi jarang dievaluasi"},"rencana_aksi":[{"id":"6fab49a7-5be3-4530-aaf4-ece94cc529a0-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 20,6 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"6fab49a7-5be3-4530-aaf4-ece94cc529a0-aksi-2","judul":"Tetapkan satu jam yang tidak diganggu pekerjaan.","alasan":"Work-Life Balance jadi sisi terendah Anda. Satu jam yang dijaga konsisten lebih realistis daripada menunggu beban kerja berkurang sendiri. Angkanya sekarang 40 dari 100.","terkait":"Work-Life Balance","jangka":"Minggu ini","ikon":"🕰️"},{"id":"6fab49a7-5be3-4530-aaf4-ece94cc529a0-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 90 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Work-Life Balance jadi sisi kesejahteraan terendah Anda (40 dari 100), sementara Kenyamanan Bekerja sudah kuat di 90. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Tetapkan jam berhenti kerja setiap hari","instruksi":"Pilih satu jam sebagai batas, lalu:","contoh":["Tutup pekerjaan administrasi di jam itu.","Simpan berkas yang belum selesai untuk besok.","Beri tahu rekan terdekat soal batas itu."],"tujuan":"Batas yang diumumkan lebih mudah dijaga daripada niat yang disimpan sendiri."},{"judul":"Kelompokkan pekerjaan koreksi di satu waktu","instruksi":"Alih-alih dicicil setiap malam:","contoh":["Tentukan dua slot koreksi dalam sepekan.","Siapkan semua bahan sebelum mulai.","Kerjakan di sekolah, bukan di rumah."],"tujuan":"Pekerjaan yang dikelompokkan selesai lebih cepat dan tidak menempel sepanjang minggu."},{"judul":"Jaga satu hari tanpa pekerjaan sekolah","instruksi":"Pilih satu hari dalam sepekan, lalu:","contoh":["Jangan buka berkas pekerjaan hari itu.","Beri tahu rekan sejak awal pekan.","Isi dengan hal yang benar-benar memulihkan."],"tujuan":"Pemulihan butuh jeda yang utuh, bukan sisa waktu di sela pekerjaan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 20,6 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Kepemimpinan jadi dimensi profil organisasi terendah menurut Anda (50 dari 100, harapan 60). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Bawa pola berulang ke jalur resmi","instruksi":"Lewat rapat atau laporan rutin, sampaikan:","contoh":["Pola keputusan yang sering terlambat.","Dampaknya pada kesiapan mengajar.","Usulan jalur konfirmasi yang lebih awal."],"tujuan":"Pola yang tercatat bisa jadi bahan kebijakan, keluhan sesaat tidak."},{"judul":"Usulkan jadwal bicara rutin dengan pimpinan","instruksi":"Ajukan usulan sederhana:","contoh":["Waktu singkat berkala per unit.","Agenda dibuka dari staf, bukan dari pimpinan.","Catatan hasil yang bisa ditagih."],"tujuan":"Percakapan yang terjadwal menutup jarak lebih cepat daripada menunggu momen."},{"judul":"Minta alasan di balik keputusan besar","instruksi":"Saat ada kebijakan baru, tanyakan:","contoh":["Apa yang mendasari keputusan itu.","Pilihan apa saja yang sempat dipertimbangkan.","Bagaimana keberhasilannya akan dinilai."],"tujuan":"Kebiasaan bertanya membentuk kebiasaan menjelaskan."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
('YPS-FAMMI', 'd8a62bff-0d56-4988-95a3-db95b96a0e0c', '2026-07', '{"meta":{"responden_id":"d8a62bff-0d56-4988-95a3-db95b96a0e0c","nama_responden":"Wulan Kusuma","peran_kerja":"Guru","unit":"TK Fammi","jenjang":"TK","jenis_kelamin":"Perempuan","organisasi_id":"YPS-FAMMI","periode_id":"2026-07","nama_lembaga":"Yayasan Pendidikan Sekolah Fammi","sumber":"excel"},"header":{"hook":"Anda melihat Yayasan Pendidikan Sekolah Fammi ini sebagai \"keluarga besar yang saling menutupi kekurangan\"","sub_hook":"Profil budaya Anda paling condong ke Kekeluargaan, dengan jarak terbesar ke harapan ada di Aturan."},"bagian_budaya":{"narasi":"Budaya yang paling Anda rasakan di TK Fammi adalah Kekeluargaan (61,9 dari 100). Jarak terbesar antara kondisi sekarang dan harapan Anda ada di Aturan: Anda mengharapkan porsinya lebih kecil sekitar 15,3 poin dari yang Anda rasakan sekarang.","chart_data":[{"tipe":"Kekeluargaan","saat_ini":61.86,"harapan":68.26},{"tipe":"Inovasi","saat_ini":69.77,"harapan":65.54},{"tipe":"Orientasi","saat_ini":47.17,"harapan":54.06},{"tipe":"Aturan","saat_ini":57.85,"harapan":42.52}],"tabel_gap":[{"label":"Kekeluargaan","arah":"naik","nilai_gap":6.4},{"label":"Inovasi","arah":"turun","nilai_gap":-4.23},{"label":"Orientasi","arah":"naik","nilai_gap":6.89},{"label":"Aturan","arah":"turun","nilai_gap":-15.33}]},"bagian_kesejahteraan":{"narasi":"Kondisi kesejahteraan Anda secara umum berada di angka 77 dari 100, kategori Sangat Tinggi. Kenyamanan Bekerja jadi sisi terkuat Anda (100), sementara Pengembangan Diri paling perlu dijaga (66,7).","indeks":77,"kategori":"Sangat Tinggi","chart_data":[{"kode":"kepuasan_kepemimpinan","label":"Kepuasan pada Kepemimpinan","nilai":80,"kategori":"Sangat Tinggi"},{"kode":"kenyamanan_bekerja","label":"Kenyamanan Bekerja","nilai":100,"kategori":"Sangat Tinggi"},{"kode":"pengembangan_diri","label":"Pengembangan Diri","nilai":66.67,"kategori":"Tinggi"},{"kode":"ekspektasi","label":"Ekspektasi Terpenuhi","nilai":66.67,"kategori":"Tinggi"},{"kode":"work_life_balance","label":"Work-Life Balance","nilai":70,"kategori":"Tinggi"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Karakter Lembaga paling kuat Anda rasakan (75), sedangkan Manajemen paling rendah (55) dengan harapan 65.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":75,"kategori":"Sangat Tinggi","harapan":80,"gap":5},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":60,"kategori":"Tinggi","harapan":60,"gap":0},{"kode":"management","label":"Manajemen","nilai":55,"kategori":"Sedang","harapan":65,"gap":10},{"kode":"sinergi","label":"Sinergi Tim","nilai":60,"kategori":"Tinggi","harapan":55,"gap":-5},{"kode":"fokus","label":"Fokus Strategis","nilai":75,"kategori":"Sangat Tinggi","harapan":70,"gap":-5},{"kode":"performance","label":"Kinerja/Performa","nilai":75,"kategori":"Sangat Tinggi","harapan":65,"gap":-10}]},"bagian_cermin":"\"Pimpinan unit mau mendengar kalau ada keluhan yang disampaikan langsung.\" \"Tugas tambahan yang menumpuk di orang yang sama terus.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Kekeluargaan jadi sisi budaya yang paling terasa di TK Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Satu keterampilan apa yang ingin Anda kuasai tiga bulan ke depan, dan kapan waktunya Anda sisihkan?","jawaban_survey":{"betah":"Pimpinan unit mau mendengar kalau ada keluhan yang disampaikan langsung.","hal_menguras_energi":"Tugas tambahan yang menumpuk di orang yang sama terus.","yang_ingin_disampaikan":"Semoga ide dari guru yang lebih muda juga diberi ruang untuk dicoba.","yang_ingin_diubah":"Pelatihan dibuka untuk semua, bukan bergiliran orang yang sama.","gambaran_lembaga":"keluarga besar yang saling menutupi kekurangan"},"rencana_aksi":[{"id":"d8a62bff-0d56-4988-95a3-db95b96a0e0c-aksi-1","judul":"Coba satu keputusan kecil tanpa menunggu prosedur baru.","alasan":"Aturan terasa lebih mengikat dari yang Anda butuhkan. Mengambil satu keputusan di wilayah Anda sendiri membuktikan ruang gerak itu sebenarnya ada. Selisihnya 15,3 poin.","terkait":"Aturan","jangka":"Minggu ini","ikon":"🚪"},{"id":"d8a62bff-0d56-4988-95a3-db95b96a0e0c-aksi-2","judul":"Pilih satu keterampilan untuk didalami tiga bulan ini.","alasan":"Pengembangan Diri jadi sisi terendah Anda. Menetapkan satu fokus membuat waktu belajar yang sempit tetap membekas. Angkanya sekarang 66,7 dari 100.","terkait":"Pengembangan Diri","jangka":"3 bulan","ikon":"📚"},{"id":"d8a62bff-0d56-4988-95a3-db95b96a0e0c-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 100 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Pengembangan Diri jadi sisi kesejahteraan terendah Anda (66,7 dari 100), sementara Kenyamanan Bekerja sudah kuat di 100. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Pilih satu keterampilan, bukan banyak sekaligus","instruksi":"Tentukan satu hal untuk didalami tiga bulan ke depan:","contoh":["Satu metode mengajar tertentu.","Satu alat bantu ajar yang belum dikuasai.","Satu cara menilai yang lebih cepat."],"tujuan":"Fokus yang sempit lebih mungkin selesai daripada rencana besar tanpa waktu."},{"judul":"Sisihkan 30 menit belajar dalam sepekan","instruksi":"Blokir satu slot tetap di jadwal Anda:","contoh":["Hari dan jam yang sama tiap pekan.","Bahan yang sudah disiapkan sebelumnya.","Catatan singkat setelah selesai."],"tujuan":"Kesempatan belajar jarang datang sendiri, ia harus dijadwalkan."},{"judul":"Cari satu rekan sebagai teman belajar","instruksi":"Ajak satu orang yang minatnya dekat:","contoh":["Sepakati apa yang mau dipelajari bersama.","Tentukan kapan saling mengabari kemajuan.","Coba satu praktik di kelas masing-masing."],"tujuan":"Belajar berdua membuat komitmen lebih sulit ditinggalkan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Aturan terpaut 15,3 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Usulkan satu prosedur yang perlu disederhanakan","instruksi":"Pilih satu prosedur yang paling sering menghambat, lalu:","contoh":["Tuliskan langkah yang sebenarnya tidak perlu.","Perkirakan waktu yang bisa dihemat.","Sampaikan ke koordinator unit."],"tujuan":"Aturan yang dirapikan mengembalikan waktu ke pekerjaan utama."},{"judul":"Bantu perjelas satu alur kerja yang membingungkan","instruksi":"Bersama satu rekan, buat:","contoh":["Daftar langkah dari awal sampai selesai.","Nama orang yang bertanggung jawab tiap langkah.","Contoh berkas yang benar."],"tujuan":"Kebingungan berulang biasanya bukan soal orangnya, tapi alurnya yang tidak pernah dituliskan."},{"judul":"Sampaikan aturan yang sudah tidak relevan","instruksi":"Kalau ada aturan yang tidak lagi cocok:","contoh":["Ceritakan kapan terakhir itu berguna.","Jelaskan hambatannya sekarang.","Usulkan penggantinya, bukan cuma penghapusannya."],"tujuan":"Usulan yang membawa pengganti lebih mungkin dipertimbangkan."}]},{"locus":"system","mengapa_fokus":"Manajemen jadi dimensi profil organisasi terendah menurut Anda (55 dari 100, harapan 65). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Usulkan penyederhanaan satu laporan","instruksi":"Pilih laporan yang paling memakan waktu, lalu:","contoh":["Tandai bagian yang datanya sudah ada di tempat lain.","Hitung waktu yang habis tiap bulan.","Sampaikan ke bagian yang memintanya."],"tujuan":"Waktu administrasi yang kembali langsung terasa di jam mengajar."},{"judul":"Bantu bakukan satu alur yang sering berubah","instruksi":"Bersama unit Anda, sepakati:","contoh":["Format yang dipakai seterusnya.","Tenggat yang realistis.","Siapa yang menjawab kalau ada pertanyaan."],"tujuan":"Format yang stabil menghilangkan pekerjaan ulang yang tidak perlu."},{"judul":"Ajukan kalender kegiatan satu semester","instruksi":"Usulkan ke pimpinan:","contoh":["Kegiatan tetap yang sudah pasti.","Batas waktu penambahan kegiatan baru.","Cara mengumumkan perubahan."],"tujuan":"Kepastian jadwal adalah keluhan yang paling sering muncul dan paling mudah diperbaiki."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
('YPS-FAMMI', '40a1d0c0-cb56-4922-b147-49db775bcc31', '2026-07', '{"meta":{"responden_id":"40a1d0c0-cb56-4922-b147-49db775bcc31","nama_responden":"Prita Marlina","peran_kerja":"Guru","unit":"TK Fammi","jenjang":"TK","jenis_kelamin":"Perempuan","organisasi_id":"YPS-FAMMI","periode_id":"2026-07","nama_lembaga":"Yayasan Pendidikan Sekolah Fammi","sumber":"excel"},"header":{"hook":"Anda melihat Yayasan Pendidikan Sekolah Fammi ini sebagai \"kapal yang jalan terus tanpa sempat berhenti\"","sub_hook":"Profil budaya Anda paling condong ke Kekeluargaan, dengan jarak terbesar ke harapan ada di Inovasi."},"bagian_budaya":{"narasi":"Budaya yang paling Anda rasakan di TK Fammi adalah Kekeluargaan (52,2 dari 100). Jarak terbesar antara kondisi sekarang dan harapan Anda ada di Inovasi: Anda mengharapkan porsinya lebih besar sekitar 33,1 poin dari yang Anda rasakan sekarang.","chart_data":[{"tipe":"Kekeluargaan","saat_ini":52.17,"harapan":52.17},{"tipe":"Inovasi","saat_ini":32.47,"harapan":65.54},{"tipe":"Orientasi","saat_ini":22.76,"harapan":26.31},{"tipe":"Aturan","saat_ini":31.09,"harapan":27.43}],"tabel_gap":[{"label":"Kekeluargaan","arah":"tetap","nilai_gap":0},{"label":"Inovasi","arah":"naik","nilai_gap":33.07},{"label":"Orientasi","arah":"naik","nilai_gap":3.55},{"label":"Aturan","arah":"turun","nilai_gap":-3.66}]},"bagian_kesejahteraan":{"narasi":"Kondisi kesejahteraan Anda secara umum berada di angka 55 dari 100, kategori Sedang. Kenyamanan Bekerja jadi sisi terkuat Anda (90), sementara Work-Life Balance paling perlu dijaga (20).","indeks":55,"kategori":"Sedang","chart_data":[{"kode":"kepuasan_kepemimpinan","label":"Kepuasan pada Kepemimpinan","nilai":53.33,"kategori":"Sedang"},{"kode":"kenyamanan_bekerja","label":"Kenyamanan Bekerja","nilai":90,"kategori":"Sangat Tinggi"},{"kode":"pengembangan_diri","label":"Pengembangan Diri","nilai":46.67,"kategori":"Sedang"},{"kode":"ekspektasi","label":"Ekspektasi Terpenuhi","nilai":66.67,"kategori":"Tinggi"},{"kode":"work_life_balance","label":"Work-Life Balance","nilai":20,"kategori":"Sangat Rendah"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Fokus Strategis paling kuat Anda rasakan (50), sedangkan Manajemen paling rendah (35) dengan harapan 55.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":45,"kategori":"Sedang","harapan":50,"gap":5},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":45,"kategori":"Sedang","harapan":45,"gap":0},{"kode":"management","label":"Manajemen","nilai":35,"kategori":"Rendah","harapan":55,"gap":20},{"kode":"sinergi","label":"Sinergi Tim","nilai":45,"kategori":"Sedang","harapan":55,"gap":10},{"kode":"fokus","label":"Fokus Strategis","nilai":50,"kategori":"Sedang","harapan":60,"gap":10},{"kode":"performance","label":"Kinerja/Performa","nilai":50,"kategori":"Sedang","harapan":45,"gap":-5}]},"bagian_cermin":"\"Suasana kerjanya hangat, tidak ada yang dibiarkan sendirian waktu kewalahan.\" \"Tugas tambahan yang menumpuk di orang yang sama terus.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Kekeluargaan jadi sisi budaya yang paling terasa di TK Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Jam berapa Anda ingin benar-benar berhenti bekerja hari ini, dan apa yang perlu disiapkan supaya itu terjadi?","jawaban_survey":{"betah":"Suasana kerjanya hangat, tidak ada yang dibiarkan sendirian waktu kewalahan.","hal_menguras_energi":"Tugas tambahan yang menumpuk di orang yang sama terus.","yang_ingin_disampaikan":"Semoga ide dari guru yang lebih muda juga diberi ruang untuk dicoba.","yang_ingin_diubah":"Ada waktu khusus untuk mencoba metode mengajar baru.","gambaran_lembaga":"kapal yang jalan terus tanpa sempat berhenti"},"rencana_aksi":[{"id":"40a1d0c0-cb56-4922-b147-49db775bcc31-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 33,1 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"40a1d0c0-cb56-4922-b147-49db775bcc31-aksi-2","judul":"Tetapkan satu jam yang tidak diganggu pekerjaan.","alasan":"Work-Life Balance jadi sisi terendah Anda. Satu jam yang dijaga konsisten lebih realistis daripada menunggu beban kerja berkurang sendiri. Angkanya sekarang 20 dari 100.","terkait":"Work-Life Balance","jangka":"Minggu ini","ikon":"🕰️"},{"id":"40a1d0c0-cb56-4922-b147-49db775bcc31-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 90 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Work-Life Balance jadi sisi kesejahteraan terendah Anda (20 dari 100), sementara Kenyamanan Bekerja sudah kuat di 90. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Tetapkan jam berhenti kerja setiap hari","instruksi":"Pilih satu jam sebagai batas, lalu:","contoh":["Tutup pekerjaan administrasi di jam itu.","Simpan berkas yang belum selesai untuk besok.","Beri tahu rekan terdekat soal batas itu."],"tujuan":"Batas yang diumumkan lebih mudah dijaga daripada niat yang disimpan sendiri."},{"judul":"Kelompokkan pekerjaan koreksi di satu waktu","instruksi":"Alih-alih dicicil setiap malam:","contoh":["Tentukan dua slot koreksi dalam sepekan.","Siapkan semua bahan sebelum mulai.","Kerjakan di sekolah, bukan di rumah."],"tujuan":"Pekerjaan yang dikelompokkan selesai lebih cepat dan tidak menempel sepanjang minggu."},{"judul":"Jaga satu hari tanpa pekerjaan sekolah","instruksi":"Pilih satu hari dalam sepekan, lalu:","contoh":["Jangan buka berkas pekerjaan hari itu.","Beri tahu rekan sejak awal pekan.","Isi dengan hal yang benar-benar memulihkan."],"tujuan":"Pemulihan butuh jeda yang utuh, bukan sisa waktu di sela pekerjaan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 33,1 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Manajemen jadi dimensi profil organisasi terendah menurut Anda (35 dari 100, harapan 55). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Usulkan penyederhanaan satu laporan","instruksi":"Pilih laporan yang paling memakan waktu, lalu:","contoh":["Tandai bagian yang datanya sudah ada di tempat lain.","Hitung waktu yang habis tiap bulan.","Sampaikan ke bagian yang memintanya."],"tujuan":"Waktu administrasi yang kembali langsung terasa di jam mengajar."},{"judul":"Bantu bakukan satu alur yang sering berubah","instruksi":"Bersama unit Anda, sepakati:","contoh":["Format yang dipakai seterusnya.","Tenggat yang realistis.","Siapa yang menjawab kalau ada pertanyaan."],"tujuan":"Format yang stabil menghilangkan pekerjaan ulang yang tidak perlu."},{"judul":"Ajukan kalender kegiatan satu semester","instruksi":"Usulkan ke pimpinan:","contoh":["Kegiatan tetap yang sudah pasti.","Batas waktu penambahan kegiatan baru.","Cara mengumumkan perubahan."],"tujuan":"Kepastian jadwal adalah keluhan yang paling sering muncul dan paling mudah diperbaiki."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
