gi"},{"kode":"work_life_balance","label":"Work-Life Balance","nilai":70,"kategori":"Tinggi"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Karakter Lembaga paling kuat Anda rasakan (70), sedangkan Kepemimpinan paling rendah (60) dengan harapan 65.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":70,"kategori":"Tinggi","harapan":65,"gap":-5},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":60,"kategori":"Tinggi","harapan":65,"gap":5},{"kode":"management","label":"Manajemen","nilai":70,"kategori":"Tinggi","harapan":50,"gap":-20},{"kode":"sinergi","label":"Sinergi Tim","nilai":60,"kategori":"Tinggi","harapan":65,"gap":5},{"kode":"fokus","label":"Fokus Strategis","nilai":65,"kategori":"Tinggi","harapan":70,"gap":5},{"kode":"performance","label":"Kinerja/Performa","nilai":65,"kategori":"Tinggi","harapan":75,"gap":10}]},"bagian_cermin":"\"Saya masih bisa belajar banyak dari rekan yang lebih senior.\" \"Jadwal kegiatan tambahan yang sering muncul mendadak.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Kekeluargaan jadi sisi budaya yang paling terasa di TK Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Satu hal apa yang ingin Anda tanyakan langsung ke pimpinan unit bulan ini, yang selama ini cuma Anda simpan sendiri?","jawaban_survey":{"betah":"Saya masih bisa belajar banyak dari rekan yang lebih senior.","hal_menguras_energi":"Jadwal kegiatan tambahan yang sering muncul mendadak.","yang_ingin_disampaikan":"Saya berharap keputusan sekolah dijelaskan alasannya ke semua staf.","yang_ingin_diubah":"Jadwal kegiatan dipetakan lebih awal, minimal satu bulan di depan.","gambaran_lembaga":"tempat menitipkan harapan orang tua murid"},"rencana_aksi":[{"id":"e046fc77-ad41-454b-b395-a53c493c4d08-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 12,4 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"e046fc77-ad41-454b-b395-a53c493c4d08-aksi-2","judul":"Bawa satu masalah nyata ke pimpinan unit.","alasan":"Kepuasan pada Kepemimpinan jadi sisi terendah Anda. Menyampaikan satu masalah konkret dengan usulan solusinya membuka percakapan yang selama ini tertunda. Angkanya sekarang 66,7 dari 100.","terkait":"Kepuasan pada Kepemimpinan","jangka":"Bulan ini","ikon":"🗣️"},{"id":"e046fc77-ad41-454b-b395-a53c493c4d08-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 90 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Kepuasan pada Kepemimpinan jadi sisi kesejahteraan terendah Anda (66,7 dari 100), sementara Kenyamanan Bekerja sudah kuat di 90. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Catat pola masalah sebelum menyampaikannya","instruksi":"Selama dua minggu, catat setiap kali:","contoh":["Keputusan yang tidak jelas dasarnya.","Informasi yang datang terlambat.","Dampaknya pada pekerjaan Anda hari itu."],"tujuan":"Supaya yang Anda sampaikan berupa pola, bukan kesan sesaat."},{"judul":"Siapkan satu usulan, bukan cuma keluhan","instruksi":"Untuk satu masalah yang paling sering muncul, tuliskan:","contoh":["Apa yang terjadi sekarang.","Apa yang Anda usulkan.","Apa yang Anda siap kerjakan sendiri."],"tujuan":"Percakapan dengan pimpinan berjalan lebih jauh kalau ada usulan konkret di dalamnya."},{"judul":"Pilih waktu bicara yang bukan saat genting","instruksi":"Cari satu momen tenang untuk bicara, misalnya:","contoh":["Setelah jam mengajar terakhir.","Di luar minggu ujian.","Bukan lewat pesan singkat."],"tujuan":"Isi pembicaraan lebih terdengar kal