('YPS-FAMMI', '2071fe3d-2d58-4d80-89b5-a752e4bbcbc7', '2026-07', '{"meta":{"responden_id":"2071fe3d-2d58-4d80-89b5-a752e4bbcbc7","nama_responden":"Eko Wijaya","peran_kerja":"Guru","unit":"SD Fammi","jenjang":"SD","jenis_kelamin":"Laki-laki","organisasi_id":"YPS-FAMMI","periode_id":"2026-07","nama_lembaga":"Yayasan Pendidikan Sekolah Fammi","sumber":"excel"},"header":{"hook":"Anda melihat Yayasan Pendidikan Sekolah Fammi ini sebagai \"ruang belajar bersama, bukan cuma tempat mengajar\"","sub_hook":"Profil budaya Anda paling condong ke Kekeluargaan, dengan jarak terbesar ke harapan ada di Inovasi."},"bagian_budaya":{"narasi":"Budaya yang paling Anda rasakan di SD Fammi adalah Kekeluargaan (61,9 dari 100). Jarak terbesar antara kondisi sekarang dan harapan Anda ada di Inovasi: Anda mengharapkan porsinya lebih besar sekitar 20,9 poin dari yang Anda rasakan sekarang.","chart_data":[{"tipe":"Kekeluargaan","saat_ini":61.86,"harapan":55.47},{"tipe":"Inovasi","saat_ini":61.32,"harapan":82.2},{"tipe":"Orientasi","saat_ini":54.06,"harapan":57.61},{"tipe":"Aturan","saat_ini":50.3,"harapan":42.52}],"tabel_gap":[{"label":"Kekeluargaan","arah":"turun","nilai_gap":-6.39},{"label":"Inovasi","arah":"naik","nilai_gap":20.88},{"label":"Orientasi","arah":"naik","nilai_gap":3.55},{"label":"Aturan","arah":"turun","nilai_gap":-7.78}]},"bagian_kesejahteraan":{"narasi":"Kondisi kesejahteraan Anda secara umum berada di angka 68 dari 100, kategori Tinggi. Kepuasan pada Kepemimpinan jadi sisi terkuat Anda (80), sementara Work-Life Balance paling perlu dijaga (50).","indeks":68,"kategori":"Tinggi","chart_data":[{"kode":"kepuasan_kepemimpinan","label":"Kepuasan pada Kepemimpinan","nilai":80,"kategori":"Sangat Tinggi"},{"kode":"kenyamanan_bekerja","label":"Kenyamanan Bekerja","nilai":70,"kategori":"Tinggi"},{"kode":"pengembangan_diri","label":"Pengembangan Diri","nilai":60,"kategori":"Tinggi"},{"kode":"ekspektasi","label":"Ekspektasi Terpenuhi","nilai":80,"kategori":"Sangat Tinggi"},{"kode":"work_life_balance","label":"Work-Life Balance","nilai":50,"kategori":"Sedang"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Karakter Lembaga paling kuat Anda rasakan (80), sedangkan Kepemimpinan paling rendah (55) dengan harapan 60.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":80,"kategori":"Sangat Tinggi","harapan":75,"gap":-5},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":55,"kategori":"Sedang","harapan":60,"gap":5},{"kode":"management","label":"Manajemen","nilai":65,"kategori":"Tinggi","harapan":75,"gap":10},{"kode":"sinergi","label":"Sinergi Tim","nilai":60,"kategori":"Tinggi","harapan":60,"gap":0},{"kode":"fokus","label":"Fokus Strategis","nilai":65,"kategori":"Tinggi","harapan":60,"gap":-5},{"kode":"performance","label":"Kinerja/Performa","nilai":65,"kategori":"Tinggi","harapan":70,"gap":5}]},"bagian_cermin":"\"Saya masih bisa belajar banyak dari rekan yang lebih senior.\" \"Menunggu keputusan yang tidak jelas siapa yang berwenang.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Kekeluargaan jadi sisi budaya yang paling terasa di SD Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Jam berapa Anda ingin benar-benar berhenti bekerja hari ini, dan apa yang perlu disiapkan supaya itu terjadi?","jawaban_survey":{"betah":"Saya masih bisa belajar banyak dari rekan yang lebih senior.","hal_menguras_energi":"Menunggu keputusan yang tidak jelas siapa yang berwenang.","yang_ingin_disampaikan":"Beban administrasi tolong ditinjau ulang supaya waktu mengajar tidak terpotong.","yang_ingin_diubah":"Ada waktu khusus untuk mencoba metode mengajar baru.","gambaran_lembaga":"ruang belajar bersama, bukan cuma tempat mengajar"},"rencana_aksi":[{"id":"2071fe3d-2d58-4d80-89b5-a752e4bbcbc7-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 20,9 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"2071fe3d-2d58-4d80-89b5-a752e4bbcbc7-aksi-2","judul":"Tetapkan satu jam yang tidak diganggu pekerjaan.","alasan":"Work-Life Balance jadi sisi terendah Anda. Satu jam yang dijaga konsisten lebih realistis daripada menunggu beban kerja berkurang sendiri. Angkanya sekarang 50 dari 100.","terkait":"Work-Life Balance","jangka":"Minggu ini","ikon":"🕰️"},{"id":"2071fe3d-2d58-4d80-89b5-a752e4bbcbc7-aksi-3","judul":"Jadi penyambung suara rekan ke pimpinan.","alasan":"Kepuasan Anda pada kepemimpinan jadi yang tertinggi. Kepercayaan itu paling berguna kalau dipakai membawa masukan rekan yang belum berani menyampaikan. Angkanya 80 dari 100.","terkait":"Kepuasan pada Kepemimpinan","jangka":"3 bulan","ikon":"🔗"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Work-Life Balance jadi sisi kesejahteraan terendah Anda (50 dari 100), sementara Kepuasan pada Kepemimpinan sudah kuat di 80. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Tetapkan jam berhenti kerja setiap hari","instruksi":"Pilih satu jam sebagai batas, lalu:","contoh":["Tutup pekerjaan administrasi di jam itu.","Simpan berkas yang belum selesai untuk besok.","Beri tahu rekan terdekat soal batas itu."],"tujuan":"Batas yang diumumkan lebih mudah dijaga daripada niat yang disimpan sendiri."},{"judul":"Kelompokkan pekerjaan koreksi di satu waktu","instruksi":"Alih-alih dicicil setiap malam:","contoh":["Tentukan dua slot koreksi dalam sepekan.","Siapkan semua bahan sebelum mulai.","Kerjakan di sekolah, bukan di rumah."],"tujuan":"Pekerjaan yang dikelompokkan selesai lebih cepat dan tidak menempel sepanjang minggu."},{"judul":"Jaga satu hari tanpa pekerjaan sekolah","instruksi":"Pilih satu hari dalam sepekan, lalu:","contoh":["Jangan buka berkas pekerjaan hari itu.","Beri tahu rekan sejak awal pekan.","Isi dengan hal yang benar-benar memulihkan."],"tujuan":"Pemulihan butuh jeda yang utuh, bukan sisa waktu di sela pekerjaan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 20,9 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Kepemimpinan jadi dimensi profil organisasi terendah menurut Anda (55 dari 100, harapan 60). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Bawa pola berulang ke jalur resmi","instruksi":"Lewat rapat atau laporan rutin, sampaikan:","contoh":["Pola keputusan yang sering terlambat.","Dampaknya pada kesiapan mengajar.","Usulan jalur konfirmasi yang lebih awal."],"tujuan":"Pola yang tercatat bisa jadi bahan kebijakan, keluhan sesaat tidak."},{"judul":"Usulkan jadwal bicara rutin dengan pimpinan","instruksi":"Ajukan usulan sederhana:","contoh":["Waktu singkat berkala per unit.","Agenda dibuka dari staf, bukan dari pimpinan.","Catatan hasil yang bisa ditagih."],"tujuan":"Percakapan yang terjadwal menutup jarak lebih cepat daripada menunggu momen."},{"judul":"Minta alasan di balik keputusan besar","instruksi":"Saat ada kebijakan baru, tanyakan:","contoh":["Apa yang mendasari keputusan itu.","Pilihan apa saja yang sempat dipertimbangkan.","Bagaimana keberhasilannya akan dinilai."],"tujuan":"Kebiasaan bertanya membentuk kebiasaan menjelaskan."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
