kode":"work_life_balance","label":"Work-Life Balance","nilai":50,"kategori":"Sedang"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Kinerja/Performa paling kuat Anda rasakan (75), sedangkan Manajemen paling rendah (55) dengan harapan 60.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":70,"kategori":"Tinggi","harapan":80,"gap":10},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":60,"kategori":"Tinggi","harapan":60,"gap":0},{"kode":"management","label":"Manajemen","nilai":55,"kategori":"Sedang","harapan":60,"gap":5},{"kode":"sinergi","label":"Sinergi Tim","nilai":60,"kategori":"Tinggi","harapan":55,"gap":-5},{"kode":"fokus","label":"Fokus Strategis","nilai":65,"kategori":"Tinggi","harapan":70,"gap":5},{"kode":"performance","label":"Kinerja/Performa","nilai":75,"kategori":"Sangat Tinggi","harapan":60,"gap":-15}]},"bagian_cermin":"\"Rekan satu jenjang gampang diajak diskusi kalau ada murid yang butuh perhatian khusus.\" \"Jadwal kegiatan tambahan yang sering muncul mendadak.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Kekeluargaan jadi sisi budaya yang paling terasa di SD Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Jam berapa Anda ingin benar-benar berhenti bekerja hari ini, dan apa yang perlu disiapkan supaya itu terjadi?","jawaban_survey":{"betah":"Rekan satu jenjang gampang diajak diskusi kalau ada murid yang butuh perhatian khusus.","hal_menguras_energi":"Jadwal kegiatan tambahan yang sering muncul mendadak.","yang_ingin_disampaikan":"Semoga ide dari guru yang lebih muda juga diberi ruang untuk dicoba.","yang_ingin_diubah":"Jalur menyampaikan ide dibuat jelas, tidak berhenti di tengah jalan.","gambaran_lembaga":"tempat kerja yang hangat tapi jadwalnya padat"},"rencana_aksi":[{"id":"c9c78097-a2e8-4a85-819f-87d624cafa4d-aksi-1","judul":"Pisahkan urusan pribadi dan urusan kerja di forum unit.","alasan":"Anda merasakan sisi kekeluargaan lebih besar dari yang Anda butuhkan. Kehangatan tetap terjaga kalau keputusan kerja punya forumnya sendiri. Selisihnya 9,7 poin.","terkait":"Kekeluargaan","jangka":"Bulan ini","ikon":"🧭"},{"id":"c9c78097-a2e8-4a85-819f-87d624cafa4d-aksi-2","judul":"Tetapkan satu jam yang tidak diganggu pekerjaan.","alasan":"Work-Life Balance jadi sisi terendah Anda. Satu jam yang dijaga konsisten lebih realistis daripada menunggu beban kerja berkurang sendiri. Angkanya sekarang 50 dari 100.","terkait":"Work-Life Balance","jangka":"Minggu ini","ikon":"🕰️"},{"id":"c9c78097-a2e8-4a85-819f-87d624cafa4d-aksi-3","judul":"Ceritakan alasan Anda bertahan ke rekan yang ragu.","alasan":"Ekspektasi Terpenuhi jadi sisi terkuat Anda. Cerita yang jujur lebih menular daripada ajakan untuk bertahan. Angkanya 86,7 dari 100.","terkait":"Ekspektasi Terpenuhi","jangka":"3 bulan","ikon":"🌤️"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Work-Life Balance jadi sisi kesejahteraan terendah Anda (50 dari 100), sementara Ekspektasi Terpenuhi sudah kuat di 86,7. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Tetapkan jam berhenti kerja setiap hari","instruksi":"Pilih satu jam sebagai batas, lalu:","contoh":["Tutup pekerjaan administrasi di jam itu.","Simpan berkas yang belum selesai untuk besok.","Beri tahu rekan terdekat soal batas itu."],"tujuan":"Batas yang diumumkan lebih mudah dijaga daripada niat yang disimpan sendiri."},{"judul":"Kelompokkan pekerjaan koreksi di satu waktu","instruksi":"Alih-alih dicicil setiap malam:","contoh":["Tentukan dua slot koreksi dalam sepekan.","Siapkan semua bahan sebelum mulai.","Kerjakan di sekolah, bukan di rumah."],"tujuan":"Pekerjaan yang dikelompokkan selesai lebih cepat dan tidak menempel sepanjang minggu."},{"judul":"Jaga satu hari tanpa pekerjaan sekolah","instruksi":"Pilih satu hari dalam sepekan, lalu:","contoh":["Jangan buka berkas pekerjaan hari itu.","Beri tahu rekan sejak awal pekan.","Isi dengan hal yang benar-benar memulihkan."],"tujuan":"Pemulihan butuh jeda yang utuh, bukan sisa waktu di sela pekerjaan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Kekeluargaan terpaut 9,7 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Mulai satu kebiasaan menyapa di unit","instruksi":"Di pekan berikutnya, coba:","contoh":["Sapa rekan yang jarang Anda ajak bicara.","Tanyakan kabar pekerjaannya, bukan cuma agendanya.","Lakukan berulang, bukan sekali."],"tujuan":"Kedekatan tumbuh dari kebiasaan kecil yang diulang, bukan dari acara besar."},{"judul":"Usulkan satu momen kumpul tanpa agenda kerja","instruksi":"Sampaikan ke koordinator unit:","contoh":["Waktu singkat setelah rapat rutin.","Tanpa materi dan tanpa laporan.","Bergantian yang menyiapkan."],"tujuan":"Ruang bicara di luar agenda kerja membuat masalah kecil ketahuan lebih awal."},{"judul":"Temani satu rekan yang sedang kewalahan","instruksi":"Kalau ada rekan yang jelas kelebihan beban:","contoh":["Tawarkan bantuan yang spesifik, bukan basa-basi.","Ambil satu bagian pekerjaannya.","Ceritakan ke koordinator kalau polanya berulang."],"tujuan":"Kekeluargaan terasa nyata saat beban benar-benar berpindah, bukan cuma disimpati."}]},{"locus":"system","mengapa_fokus":"Manajemen jadi dimensi profil organisasi terendah menurut Anda (55 dari 100, harapan 60). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Usulkan penyederhanaan satu laporan","instruksi":"Pilih laporan yang paling memakan waktu, lalu:","contoh":["Tandai bagian yang datanya sudah ada di tempat lain.","Hitung waktu yang habis tiap bulan.","Sampaikan ke bagian yang memintanya."],"tujuan":"Waktu administrasi yang kembali langsung terasa di jam mengajar."},{"judul":"Bantu bakukan satu alur yang sering berubah","instruksi":"Bersama unit Anda, sepakati:","contoh":["Format yang dipakai seterusnya.","Tenggat yang realistis.","Siapa yang menjawab kalau ada pertanyaan."],"tujuan":"Format yang stabil menghilangkan pekerjaan ulang yang tidak perlu."},{"judul":"Ajukan kalender kegiatan satu semester","instruksi":"Usulkan ke pimpinan:","contoh":["Kegiatan tetap yang sudah pasti.","Batas waktu penambahan kegiatan baru.","Cara mengumumkan perubahan."],"tujuan":"Kepastian jadwal adalah keluhan yang paling sering muncul dan paling mudah diperbaiki."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now())
