nce","label":"Work-Life Balance","nilai":60,"kategori":"Tinggi"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Kinerja/Performa paling kuat Anda rasakan (80), sedangkan Sinergi Tim paling rendah (60) dengan harapan 55.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":70,"kategori":"Tinggi","harapan":85,"gap":15},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":65,"kategori":"Tinggi","harapan":65,"gap":0},{"kode":"management","label":"Manajemen","nilai":65,"kategori":"Tinggi","harapan":75,"gap":10},{"kode":"sinergi","label":"Sinergi Tim","nilai":60,"kategori":"Tinggi","harapan":55,"gap":-5},{"kode":"fokus","label":"Fokus Strategis","nilai":60,"kategori":"Tinggi","harapan":65,"gap":5},{"kode":"performance","label":"Kinerja/Performa","nilai":80,"kategori":"Sangat Tinggi","harapan":70,"gap":-10}]},"bagian_cermin":"\"Rekan satu jenjang gampang diajak diskusi kalau ada murid yang butuh perhatian khusus.\" \"Tugas tambahan yang menumpuk di orang yang sama terus.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Kekeluargaan jadi sisi budaya yang paling terasa di SD Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Satu perubahan kecil apa di ruang kerja Anda yang bisa Anda kerjakan sendiri minggu ini?","jawaban_survey":{"betah":"Rekan satu jenjang gampang diajak diskusi kalau ada murid yang butuh perhatian khusus.","hal_menguras_energi":"Tugas tambahan yang menumpuk di orang yang sama terus.","yang_ingin_disampaikan":"Kalau bisa pelatihan dibuka untuk semua guru, bukan bergiliran orang yang sama.","yang_ingin_diubah":"Jalur menyampaikan ide dibuat jelas, tidak berhenti di tengah jalan.","gambaran_lembaga":"tempat kerja yang hangat tapi jadwalnya padat"},"rencana_aksi":[{"id":"1acd9265-0f9b-417c-90b9-bc4076500f93-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 29,1 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"1acd9265-0f9b-417c-90b9-bc4076500f93-aksi-2","judul":"Perbaiki satu hal di ruang kerja Anda sendiri.","alasan":"Kenyamanan Bekerja jadi sisi terendah Anda. Mulai dari yang benar-benar bisa Anda ubah sendiri, bukan dari yang butuh keputusan orang lain. Angkanya sekarang 60 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"Minggu ini","ikon":"🪑"},{"id":"1acd9265-0f9b-417c-90b9-bc4076500f93-aksi-3","judul":"Ceritakan alasan Anda bertahan ke rekan yang ragu.","alasan":"Ekspektasi Terpenuhi jadi sisi terkuat Anda. Cerita yang jujur lebih menular daripada ajakan untuk bertahan. Angkanya 80 dari 100.","terkait":"Ekspektasi Terpenuhi","jangka":"3 bulan","ikon":"🌤️"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Kenyamanan Bekerja jadi sisi kesejahteraan terendah Anda (60 dari 100), sementara Ekspektasi Terpenuhi sudah kuat di 80. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Rapikan satu sudut ruang kerja Anda","instruksi":"Minggu ini, kerjakan satu hal kecil:","contoh":["Rapikan berkas yang menumpuk di meja.","Pindahkan barang yang tidak lagi dipakai.","Siapkan satu tempat tetap untuk bahan ajar."],"tujuan":"Kenyamanan sering berubah dari hal kecil yang sepenuhnya di tangan Anda."},{"judul":"Sepakati satu kebiasaan kerja dengan rekan terdekat","instruksi":"Bicarakan dengan satu rekan satu ruang:","contoh":["Jam mana yang dipakai untuk kerja fokus.","Cara menitip pesan saat sedang mengajar.","Batas suara di ruang bersama."],"tujuan":"Sebagian besar gangguan kenyamanan bisa selesai lewat satu kesepakatan kecil."},{"judul":"Kenali pemicu tidak nyaman Anda sendiri","instruksi":"Selama seminggu, tandai:","contoh":["Jam berapa Anda paling terganggu.","Kegiatan apa yang membuatnya muncul.","Apa yang biasanya menenangkan."],"tujuan":"Pola yang dikenali lebih mudah disiasati daripada rasa yang cuma dirasakan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 29,1 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Sinergi Tim jadi dimensi profil organisasi terendah menurut Anda (60 dari 100, harapan 55). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Usulkan satu pertemuan lintas jenjang","instruksi":"Sampaikan ke pimpinan unit:","contoh":["Topik yang dibutuhkan dua jenjang sekaligus.","Waktu yang paling mungkin untuk keduanya.","Hasil yang diharapkan dari pertemuan itu."],"tujuan":"Silo antarjenjang jarang hilang sendiri, ia perlu satu pertemuan pertama."},{"judul":"Bagikan bahan ajar Anda ke jenjang lain","instruksi":"Pilih satu bahan yang bisa dipakai ulang:","contoh":["Kirim ke rekan jenjang di atas atau di bawah.","Jelaskan konteks pemakaiannya.","Minta masukan balik."],"tujuan":"Kerja sama tumbuh lebih cepat lewat pertukaran yang nyata daripada lewat ajakan."},{"judul":"Usulkan satu proyek kecil bersama","instruksi":"Ajukan proyek yang butuh dua unit:","contoh":["Lingkupnya kecil dan selesai dalam satu bulan.","Tugas tiap unit jelas.","Ada hasil yang bisa dilihat murid."],"tujuan":"Keberhasilan kecil lintas unit membuka jalan untuk yang lebih besar."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
