fe_balance","label":"Work-Life Balance","nilai":70,"kategori":"Tinggi"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Karakter Lembaga paling kuat Anda rasakan (75), sedangkan Sinergi Tim paling rendah (45) dengan harapan 60.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":75,"kategori":"Sangat Tinggi","harapan":80,"gap":5},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":65,"kategori":"Tinggi","harapan":60,"gap":-5},{"kode":"management","label":"Manajemen","nilai":60,"kategori":"Tinggi","harapan":50,"gap":-10},{"kode":"sinergi","label":"Sinergi Tim","nilai":45,"kategori":"Sedang","harapan":60,"gap":15},{"kode":"fokus","label":"Fokus Strategis","nilai":70,"kategori":"Tinggi","harapan":75,"gap":5},{"kode":"performance","label":"Kinerja/Performa","nilai":75,"kategori":"Sangat Tinggi","harapan":60,"gap":-15}]},"bagian_cermin":"\"Pimpinan unit mau mendengar kalau ada keluhan yang disampaikan langsung.\" \"Tugas tambahan yang menumpuk di orang yang sama terus.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Kekeluargaan jadi sisi budaya yang paling terasa di SD Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Satu hal apa yang ingin Anda tanyakan langsung ke pimpinan unit bulan ini, yang selama ini cuma Anda simpan sendiri?","jawaban_survey":{"betah":"Pimpinan unit mau mendengar kalau ada keluhan yang disampaikan langsung.","hal_menguras_energi":"Tugas tambahan yang menumpuk di orang yang sama terus.","yang_ingin_disampaikan":"Mohon kejelasan soal jenjang karier dan penghargaan kerja.","yang_ingin_diubah":"Kegiatan lintas jenjang diperbanyak supaya tidak jalan sendiri-sendiri.","gambaran_lembaga":"tempat belajar yang ramai tapi menyenangkan"},"rencana_aksi":[{"id":"2726147a-1ec7-43ff-88fe-26c864fa0a20-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 24,9 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"2726147a-1ec7-43ff-88fe-26c864fa0a20-aksi-2","judul":"Bawa satu masalah nyata ke pimpinan unit.","alasan":"Kepuasan pada Kepemimpinan jadi sisi terendah Anda. Menyampaikan satu masalah konkret dengan usulan solusinya membuka percakapan yang selama ini tertunda. Angkanya sekarang 60 dari 100.","terkait":"Kepuasan pada Kepemimpinan","jangka":"Bulan ini","ikon":"🗣️"},{"id":"2726147a-1ec7-43ff-88fe-26c864fa0a20-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 100 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Kepuasan pada Kepemimpinan jadi sisi kesejahteraan terendah Anda (60 dari 100), sementara Kenyamanan Bekerja sudah kuat di 100. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Catat pola masalah sebelum menyampaikannya","instruksi":"Selama dua minggu, catat setiap kali:","contoh":["Keputusan yang tidak jelas dasarnya.","Informasi yang datang terlambat.","Dampaknya pada pekerjaan Anda hari itu."],"tujuan":"Supaya yang Anda sampaikan berupa pola, bukan kesan sesaat."},{"judul":"Siapkan satu usulan, bukan cuma keluhan","instruksi":"Untuk satu masalah yang paling sering muncul, tuliskan:","contoh":["Apa yang terjadi sekarang.","Apa yang Anda usulkan.","Apa yang Anda siap kerjakan sendiri."],"tujuan":"Percakapan dengan pimpinan berjalan lebih jauh kalau ada usulan konkret di dalamnya."},{"judul":"Pilih waktu bicara yang bukan saat genting","instruksi":"Cari satu momen tenang untuk bicara, misalnya:","contoh":["Setelah jam mengajar terakhir.","Di luar minggu ujian.","Bukan lewat pesan singkat."],"tujuan":"Isi pembicaraan lebih terdengar kalau waktunya tepat."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 24,9 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Sinergi Tim jadi dimensi profil organisasi terendah menurut Anda (45 dari 100, harapan 60). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Usulkan satu pertemuan lintas jenjang","instruksi":"Sampaikan ke pimpinan unit:","contoh":["Topik yang dibutuhkan dua jenjang sekaligus.","Waktu yang paling mungkin untuk keduanya.","Hasil yang diharapkan dari pertemuan itu."],"tujuan":"Silo antarjenjang jarang hilang sendiri, ia perlu satu pertemuan pertama."},{"judul":"Bagikan bahan ajar Anda ke jenjang lain","instruksi":"Pilih satu bahan yang bisa dipakai ulang:","contoh":["Kirim ke rekan jenjang di atas atau di bawah.","Jelaskan konteks pemakaiannya.","Minta masukan balik."],"tujuan":"Kerja sama tumbuh lebih cepat lewat pertukaran yang nyata daripada lewat ajakan."},{"judul":"Usulkan satu proyek kecil bersama","instruksi":"Ajukan proyek yang butuh dua unit:","contoh":["Lingkupnya kecil dan selesai dalam satu bulan.","Tugas tiap unit jelas.","Ada hasil yang bisa dilihat murid."],"tujuan":"Keberhasilan kecil lintas unit membuka jalan untuk yang lebih besar."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
