_balance","label":"Work-Life Balance","nilai":60,"kategori":"Tinggi"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Karakter Lembaga paling kuat Anda rasakan (70), sedangkan Sinergi Tim paling rendah (45) dengan harapan 70.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":70,"kategori":"Tinggi","harapan":65,"gap":-5},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":70,"kategori":"Tinggi","harapan":65,"gap":-5},{"kode":"management","label":"Manajemen","nilai":60,"kategori":"Tinggi","harapan":60,"gap":0},{"kode":"sinergi","label":"Sinergi Tim","nilai":45,"kategori":"Sedang","harapan":70,"gap":25},{"kode":"fokus","label":"Fokus Strategis","nilai":60,"kategori":"Tinggi","harapan":75,"gap":15},{"kode":"performance","label":"Kinerja/Performa","nilai":60,"kategori":"Tinggi","harapan":75,"gap":15}]},"bagian_cermin":"\"Saya masih bisa belajar banyak dari rekan yang lebih senior.\" \"Menunggu keputusan yang tidak jelas siapa yang berwenang.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Kekeluargaan jadi sisi budaya yang paling terasa di SMP Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Harapan apa yang Anda bawa saat pertama bergabung, dan bagian mana yang masih pantas diperjuangkan?","jawaban_survey":{"betah":"Saya masih bisa belajar banyak dari rekan yang lebih senior.","hal_menguras_energi":"Menunggu keputusan yang tidak jelas siapa yang berwenang.","yang_ingin_disampaikan":"Mohon kejelasan soal jenjang karier dan penghargaan kerja.","yang_ingin_diubah":"Pembagian tugas tambahan lebih merata antarguru.","gambaran_lembaga":"tempat belajar yang ramai tapi menyenangkan"},"rencana_aksi":[{"id":"cfc987f6-e06e-4d9c-b1dc-252a64803075-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 24,9 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"cfc987f6-e06e-4d9c-b1dc-252a64803075-aksi-2","judul":"Tuliskan ulang harapan Anda pada peran ini.","alasan":"Ekspektasi Terpenuhi jadi sisi terendah Anda. Menuliskan harapan yang belum terpenuhi membuatnya bisa dibicarakan, bukan cuma dipendam. Angkanya sekarang 60 dari 100.","terkait":"Ekspektasi Terpenuhi","jangka":"Bulan ini","ikon":"📝"},{"id":"cfc987f6-e06e-4d9c-b1dc-252a64803075-aksi-3","judul":"Jadi penyambung suara rekan ke pimpinan.","alasan":"Kepuasan Anda pada kepemimpinan jadi yang tertinggi. Kepercayaan itu paling berguna kalau dipakai membawa masukan rekan yang belum berani menyampaikan. Angkanya 73,3 dari 100.","terkait":"Kepuasan pada Kepemimpinan","jangka":"3 bulan","ikon":"🔗"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Ekspektasi Terpenuhi jadi sisi kesejahteraan terendah Anda (60 dari 100), sementara Kepuasan pada Kepemimpinan sudah kuat di 73,3. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Tuliskan harapan awal Anda saat masuk","instruksi":"Luangkan 20 menit untuk menulis:","contoh":["Apa yang Anda bayangkan saat pertama bergabung.","Bagian mana yang sudah terpenuhi.","Bagian mana yang belum."],"tujuan":"Harapan yang tertulis bisa ditinjau, harapan yang dipendam cuma jadi kecewa."},{"judul":"Pisahkan yang bisa dan tidak bisa Anda ubah","instruksi":"Dari daftar tadi, tandai:","contoh":["Yang sepenuhnya keputusan Anda.","Yang butuh persetujuan orang lain.","Yang di luar kendali siapa pun di sini."],"tujuan":"Energi tidak habis di hal yang memang bukan wilayah Anda."},{"judul":"Bicarakan satu harapan yang paling mungkin dipenuhi","instruksi":"Pilih satu yang realistis, lalu sampaikan:","contoh":["Ke pimpinan unit, bukan lewat pihak ketiga.","Dengan alasan yang jelas.","Dengan tawaran langkah pertama dari Anda."],"tujuan":"Satu harapan yang terpenuhi memulihkan lebih banyak daripada daftar panjang yang menggantung."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 24,9 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Sinergi Tim jadi dimensi profil organisasi terendah menurut Anda (45 dari 100, harapan 70). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Usulkan satu pertemuan lintas jenjang","instruksi":"Sampaikan ke pimpinan unit:","contoh":["Topik yang dibutuhkan dua jenjang sekaligus.","Waktu yang paling mungkin untuk keduanya.","Hasil yang diharapkan dari pertemuan itu."],"tujuan":"Silo antarjenjang jarang hilang sendiri, ia perlu satu pertemuan pertama."},{"judul":"Bagikan bahan ajar Anda ke jenjang lain","instruksi":"Pilih satu bahan yang bisa dipakai ulang:","contoh":["Kirim ke rekan jenjang di atas atau di bawah.","Jelaskan konteks pemakaiannya.","Minta masukan balik."],"tujuan":"Kerja sama tumbuh lebih cepat lewat pertukaran yang nyata daripada lewat ajakan."},{"judul":"Usulkan satu proyek kecil bersama","instruksi":"Ajukan proyek yang butuh dua unit:","contoh":["Lingkupnya kecil dan selesai dalam satu bulan.","Tugas tiap unit jelas.","Ada hasil yang bisa dilihat murid."],"tujuan":"Keberhasilan kecil lintas unit membuka jalan untuk yang lebih besar."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
('YPS-FAMMI', '4e5eb343-45ae-43f7-8555-e1d16c07dbdd', '2026-07', '{"meta":{"responden_id":"4e5eb343-45ae-43f7-8555-e1d16c07dbdd","nama_responden":"Oktavia Puspita","peran_kerja":"Tenaga Kependidikan","unit":"SMP Fammi","jenjang":"SMP","jenis_kelamin":"Perempuan","organisasi_id":"YPS-FAMMI","periode_id":"2026-07","nama_lembaga":"Yayasan Pendidikan Sekolah Fammi","sumber":"excel"},"header":{"hook":"Anda melihat Yayasan Pendidikan Sekolah Fammi ini sebagai \"tempat yang tertib tapi agak kaku\"","sub_hook":"Profil budaya Anda paling condong ke Aturan, dengan jarak terbesar ke harapan ada di Aturan."},"bagian_budaya":{"narasi":"Budaya yang paling Anda rasakan di SMP Fammi adalah Aturan (73,2 dari 100). Jarak terbesar antara kondisi sekarang dan harapan Anda ada di Aturan: Anda mengharapkan porsinya lebih kecil sekitar 30,7 poin dari yang Anda rasakan sekarang.","chart_data":[{"tipe":"Kekeluargaan","saat_ini":58.57,"harapan":52.17},{"tipe":"Inovasi","saat_ini":73.75,"harapan":65.54},{"tipe":"Orientasi","saat_ini":57.61,"harapan":57.61},{"tipe":"Aturan","saat_ini":73.17,"harapan":42.52}],"tabel_gap":[{"label":"Kekeluargaan","arah":"turun","nilai_gap":-6.4},{"label":"Inovasi","arah":"turun","nilai_gap":-8.21},{"label":"Orientasi","arah":"tetap","nilai_gap":0},{"label":"Aturan","arah":"turun","nilai_gap":-30.65}]},"bagian_kesejahteraan":{"narasi":"Kondisi kesejahteraan Anda secara umum berada di angka 67 dari 100, kategori Tinggi. Kenyamanan Bekerja jadi sisi terkuat Anda (90), sementara Work-Life Balance paling perlu dijaga (40).","indeks":67,"kategori":"Tinggi","chart_data":[{"kode":"kepuasan_kepemimpinan","label":"Kepuasan pada Kepemimpinan","nilai":60,"kategori":"Tinggi"},{"kode":"kenyamanan_bekerja","label":"Kenyamanan Bekerja","nilai":90,"kategori":"Sangat Tinggi"},{"kode":"pengembangan_diri","label":"Pengembangan Diri","nilai":66.67,"kategori":"Tinggi"},{"kode":"ekspektasi","label":"Ekspektasi Terpenuhi","nilai":80,"kategori":"Sangat Tinggi"},{"kode":"work_life_balance","label":"Work-Life Balance","nilai":40,"kategori":"Rendah"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Karakter Lembaga paling kuat Anda rasakan (80), sedangkan Sinergi Tim paling rendah (65) dengan harapan 60.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":80,"kategori":"Sangat Tinggi","harapan":70,"gap":-10},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":70,"kategori":"Tinggi","harapan":55,"gap":-15},{"kode":"management","label":"Manajemen","nilai":70,"kategori":"Tinggi","harapan":60,"gap":-10},{"kode":"sinergi","label":"Sinergi Tim","nilai":65,"kategori":"Tinggi","harapan":60,"gap":-5},{"kode":"fokus","label":"Fokus Strategis","nilai":75,"kategori":"Sangat Tinggi","harapan":65,"gap":-10},{"kode":"performance","label":"Kinerja/Performa","nilai":75,"kategori":"Sangat Tinggi","harapan":65,"gap":-10}]},"bagian_cermin":"\"Saya masih bisa belajar banyak dari rekan yang lebih senior.\" \"Menunggu keputusan yang tidak jelas siapa yang berwenang.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Aturan jadi sisi budaya yang paling terasa di SMP Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Jam berapa Anda ingin benar-benar berhenti bekerja hari ini, dan apa yang perlu disiapkan supaya itu terjadi?","jawaban_survey":{"betah":"Saya masih bisa belajar banyak dari rekan yang lebih senior.","hal_menguras_energi":"Menunggu keputusan yang tidak jelas siapa yang berwenang.","yang_ingin_disampaikan":"Mohon kejelasan soal jenjang karier dan penghargaan kerja.","yang_ingin_diubah":"Ada kejelasan jenjang karier untuk guru dan tenaga kependidikan.","gambaran_lembaga":"tempat yang tertib tapi agak kaku"},"rencana_aksi":[{"id":"4e5eb343-45ae-43f7-8555-e1d16c07dbdd-aksi-1","judul":"Coba satu keputusan kecil tanpa menunggu prosedur baru.","alasan":"Aturan terasa lebih mengikat dari yang Anda butuhkan. Mengambil satu keputusan di wilayah Anda sendiri membuktikan ruang gerak itu sebenarnya ada. Selisihnya 30,7 poin.","terkait":"Aturan","jangka":"Minggu ini","ikon":"🚪"},{"id":"4e5eb343-45ae-43f7-8555-e1d16c07dbdd-aksi-2","judul":"Tetapkan satu jam yang tidak diganggu pekerjaan.","alasan":"Work-Life Balance jadi sisi terendah Anda. Satu jam yang dijaga konsisten lebih realistis daripada menunggu beban kerja berkurang sendiri. Angkanya sekarang 40 dari 100.","terkait":"Work-Life Balance","jangka":"Minggu ini","ikon":"🕰️"},{"id":"4e5eb343-45ae-43f7-8555-e1d16c07dbdd-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 90 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Work-Life Balance jadi sisi kesejahteraan terendah Anda (40 dari 100), sementara Kenyamanan Bekerja sudah kuat di 90. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Tetapkan jam berhenti kerja setiap hari","instruksi":"Pilih satu jam sebagai batas, lalu:","contoh":["Tutup pekerjaan administrasi di jam itu.","Simpan berkas yang belum selesai untuk besok.","Beri tahu rekan terdekat soal batas itu."],"tujuan":"Batas yang diumumkan lebih mudah dijaga daripada niat yang disimpan sendiri."},{"judul":"Kelompokkan pekerjaan koreksi di satu waktu","instruksi":"Alih-alih dicicil setiap malam:","contoh":["Tentukan dua slot koreksi dalam sepekan.","Siapkan semua bahan sebelum mulai.","Kerjakan di sekolah, bukan di rumah."],"tujuan":"Pekerjaan yang dikelompokkan selesai lebih cepat dan tidak menempel sepanjang minggu."},{"judul":"Jaga satu hari tanpa pekerjaan sekolah","instruksi":"Pilih satu hari dalam sepekan, lalu:","contoh":["Jangan buka berkas pekerjaan hari itu.","Beri tahu rekan sejak awal pekan.","Isi dengan hal yang benar-benar memulihkan."],"tujuan":"Pemulihan butuh jeda yang utuh, bukan sisa waktu di sela pekerjaan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Aturan terpaut 30,7 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Usulkan satu prosedur yang perlu disederhanakan","instruksi":"Pilih satu prosedur yang paling sering menghambat, lalu:","contoh":["Tuliskan langkah yang sebenarnya tidak perlu.","Perkirakan waktu yang bisa dihemat.","Sampaikan ke koordinator unit."],"tujuan":"Aturan yang dirapikan mengembalikan waktu ke pekerjaan utama."},{"judul":"Bantu perjelas satu alur kerja yang membingungkan","instruksi":"Bersama satu rekan, buat:","contoh":["Daftar langkah dari awal sampai selesai.","Nama orang yang bertanggung jawab tiap langkah.","Contoh berkas yang benar."],"tujuan":"Kebingungan berulang biasanya bukan soal orangnya, tapi alurnya yang tidak pernah dituliskan."},{"judul":"Sampaikan aturan yang sudah tidak relevan","instruksi":"Kalau ada aturan yang tidak lagi cocok:","contoh":["Ceritakan kapan terakhir itu berguna.","Jelaskan hambatannya sekarang.","Usulkan penggantinya, bukan cuma penghapusannya."],"tujuan":"Usulan yang membawa pengganti lebih mungkin dipertimbangkan."}]},{"locus":"system","mengapa_fokus":"Sinergi Tim jadi dimensi profil organisasi terendah menurut Anda (65 dari 100, harapan 60). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Usulkan satu pertemuan lintas jenjang","instruksi":"Sampaikan ke pimpinan unit:","contoh":["Topik yang dibutuhkan dua jenjang sekaligus.","Waktu yang paling mungkin untuk keduanya.","Hasil yang diharapkan dari pertemuan itu."],"tujuan":"Silo antarjenjang jarang hilang sendiri, ia perlu satu pertemuan pertama."},{"judul":"Bagikan bahan ajar Anda ke jenjang lain","instruksi":"Pilih satu bahan yang bisa dipakai ulang:","contoh":["Kirim ke rekan jenjang di atas atau di bawah.","Jelaskan konteks pemakaiannya.","Minta masukan balik."],"tujuan":"Kerja sama tumbuh lebih cepat lewat pertukaran yang nyata daripada lewat ajakan."},{"judul":"Usulkan satu proyek kecil bersama","instruksi":"Ajukan proyek yang butuh dua unit:","contoh":["Lingkupnya kecil dan selesai dalam satu bulan.","Tugas tiap unit jelas.","Ada hasil yang bisa dilihat murid."],"tujuan":"Keberhasilan kecil lintas unit membuka jalan untuk yang lebih besar."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now())
